package sentinel.example;

public final class Value {
    public boolean positive(int value) {
        return value > 0;
    }
}

fixtures.javaStrongTest:
package sentinel.example;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class ValueTest {
    @Test void checksBoundary() {
        Value subject = new Value();
        assertTrue(subject.positive(1));
        assertFalse(subject.positive(0));
        assertFalse(subject.positive(-1));
    }
}
